"""Download order pages and customer records from the local order service.

Usage: fetch.py orders|customers DATA_DIR

Accepted responses are saved under DATA_DIR, and reruns skip what is already saved.
Every request is appended to DATA_DIR/requests.log. A 401 gets a new token, a 429 or
503 waits the time the server gives, and network errors and other 5xx responses are
repeated with backoff. Any other failure stops the run.
"""
import datetime
import email.utils
import json
import os
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
PAGE_SIZE = 50
OPENER = urllib.request.build_opener(urllib.request.ProxyHandler({}))  # the service is local
TOKEN = None
LOG_PATH = None


def log(text):
    stamp = datetime.datetime.now(datetime.timezone.utc).strftime("%H:%M:%S.%f")[:-3]
    with open(LOG_PATH, "a") as f:
        f.write(f"{stamp} {text}\n")


def call(method, path, token=None):
    """Return (status, headers, body). Status is None if no HTTP response arrived."""
    req = urllib.request.Request(BASE + path, method=method)
    if token:
        req.add_header("Authorization", "Bearer " + token)
    try:
        with OPENER.open(req, timeout=30) as resp:
            return resp.status, resp.headers, resp.read()
    except urllib.error.HTTPError as e:
        return e.code, e.headers, e.read()
    except OSError as e:  # connection refused, reset or timed out
        log(f"  transport error: {e!r}")
        return None, {}, b""


def new_token():
    global TOKEN
    for attempt in range(1, 6):
        status, _, body = call("POST", "/token")
        if status == 200:
            TOKEN = json.loads(body)["token"]
            log("  new token")
            return
        log(f"  token request -> {status}")
        time.sleep(min(2 ** attempt, 30))
    raise SystemExit("could not get a token")


def ensure_token():
    if TOKEN is None:
        new_token()


def rate_limit_wait(headers, body):
    """Seconds the server asked us to wait, or None if it did not say."""
    value = headers.get("Retry-After")
    if value:
        try:
            return float(value)
        except ValueError:
            when = email.utils.parsedate_to_datetime(value)
            return max(0.0, (when - datetime.datetime.now(datetime.timezone.utc)).total_seconds())
    try:
        payload = json.loads(body)
    except ValueError:
        return None
    if isinstance(payload, dict):
        for key, val in payload.items():
            if "retry" in key.lower():
                try:
                    seconds = float(val)
                except (TypeError, ValueError):
                    continue
                return seconds / 1000 if key.lower().endswith("ms") else seconds
    return None


def parse(body, valid):
    try:
        payload = json.loads(body)
    except ValueError:
        return None
    return payload if valid(payload) else None


def is_page(payload):
    return isinstance(payload, dict) and isinstance(payload.get("items"), list)


def is_customer(cid):
    return lambda payload: isinstance(payload, dict) and payload.get("id") == cid


def fetch_json(path, label, valid, missing_ok=False):
    """GET an authenticated path and return the parsed body, or None for a 404 if missing_ok."""
    ensure_token()
    failures = expiries = 0
    while True:
        status, headers, body = call("GET", path, TOKEN)
        log(f"GET {path} [{label}] -> {status}")
        payload = parse(body, valid) if status == 200 else None
        if payload is not None:
            return payload
        if status == 401:
            expiries += 1
            if expiries > 5:
                raise SystemExit(f"{label}: still 401 after {expiries} new tokens")
            log(f"  401: {body[:200]!r}")
            new_token()
            continue
        wait = rate_limit_wait(headers, body) if status in (429, 503) else None
        if wait is not None:
            log(f"  waiting {wait}s as the server asked")
            time.sleep(max(wait, 0) + 0.5)
            continue
        if status == 429:
            raise SystemExit(f"{label}: 429 with no wait time: {dict(headers)} {body[:300]!r}")
        if status == 404 and missing_ok:
            return None
        if status is not None and status < 500 and status != 200:
            raise SystemExit(f"{label}: unexpected HTTP {status}: {body[:300]!r}")
        failures += 1
        if failures > 8:
            raise SystemExit(f"{label}: gave up after {failures} failed attempts")
        delay = min(2 ** failures, 30)
        log(f"  retrying in {delay}s")
        time.sleep(delay)


def save(path, payload):
    with open(path + ".tmp", "w") as f:
        json.dump(payload, f)
    os.replace(path + ".tmp", path)


def fetch_orders(data_dir):
    pages_dir = os.path.join(data_dir, "pages")
    os.makedirs(pages_dir, exist_ok=True)
    total_pages = None
    n = 1
    while total_pages is None or n <= total_pages:
        out = os.path.join(pages_dir, f"page-{n:03d}.json")
        if os.path.exists(out):
            with open(out) as f:
                page = json.load(f)
        else:
            page = fetch_json(f"/orders?page={n}", f"orders page {n}", is_page)
            save(out, page)
        if page["page"] != n:
            raise SystemExit(f"asked for page {n}, got page {page['page']}")
        if total_pages is None:
            total_pages = page["total_pages"]
        if page["total_pages"] != total_pages:
            raise SystemExit(f"page {n}: total_pages changed to {page['total_pages']}")
        expected_next = f"/orders?page={n + 1}" if n < total_pages else None
        if page["next"] != expected_next:
            raise SystemExit(f"page {n}: next is {page['next']!r}, expected {expected_next!r}")
        count = len(page["items"])
        if not 0 < count <= PAGE_SIZE or (n < total_pages and count != PAGE_SIZE):
            raise SystemExit(f"page {n}: {count} items")
        n += 1
    ensure_token()
    status, _, body = call("GET", f"/orders?page={total_pages + 1}", TOKEN)
    log(f"probe page {total_pages + 1} -> {status} {body[:200]!r}")
    print(f"orders: {total_pages} pages saved; probe of page {total_pages + 1} -> HTTP {status}")


def fetch_customers(data_dir):
    pages_dir = os.path.join(data_dir, "pages")
    ids = set()
    for name in sorted(os.listdir(pages_dir)):
        if name.endswith(".json"):
            with open(os.path.join(pages_dir, name)) as f:
                ids.update(item["customer_id"] for item in json.load(f)["items"])
    cust_dir = os.path.join(data_dir, "customers")
    os.makedirs(cust_dir, exist_ok=True)
    for cid in sorted(ids):
        out = os.path.join(cust_dir, f"{cid}.json")
        if os.path.exists(out):
            continue
        record = fetch_json(f"/customers/{cid}", f"customer {cid}", is_customer(cid), missing_ok=True)
        save(out, record if record is not None else {"id": cid, "missing": True})
    print(f"customers: {len(ids)} distinct customer ids saved")


if __name__ == "__main__":
    if len(sys.argv) != 3 or sys.argv[1] not in ("orders", "customers"):
        raise SystemExit(__doc__)
    os.makedirs(sys.argv[2], exist_ok=True)
    LOG_PATH = os.path.join(sys.argv[2], "requests.log")
    if sys.argv[1] == "orders":
        fetch_orders(sys.argv[2])
    else:
        fetch_customers(sys.argv[2])

